(async()=>{
  try{
    // Prefer single source of truth generated by workflow
    const sources = ['/data/pricing.json','/pricing/config.json'];
    let cfg=null;
    for (const u of sources){
      try{
        const r = await fetch(u,{cache:'no-store'});
        if (r.ok){ cfg = await r.json(); break; }
      }catch(_){}
    }
    if(!cfg) return;

    // Normalize different shapes into {id, href}
    const tiers = Array.isArray(cfg.tiers) ? cfg.tiers.map(t=>({
      id: t.id, href: t.buy_link || t.contact_url || null
    })) : Array.isArray(cfg.plans) ? cfg.plans.map(p=>({
      id: p.id, href: p.checkout_redirect || p.checkoutFallback || null
    })) : [];

    const getHref = (id)=> (tiers.find(x=>x.id===id)||{}).href;
    const m = { portfolio: 'btn-portfolio', business: 'btn-business', audit: 'btn-audit', enterprise: 'btn-audit' };
    for(const [tier, btnId] of Object.entries(m)){
      const href = getHref(tier);
      if(href) document.getElementById(btnId)?.setAttribute('href', href);
    }
  }catch(_){}
})();
